-- Synthetic fixtures ONLY in a fresh disposable Bridgeway_Validation_* database.
-- Never run this file in the real Bridgeway database. No external services are called.
SET NOCOUNT ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET ANSI_WARNINGS ON;
SET ANSI_PADDING ON;
SET ARITHABORT ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET NUMERIC_ROUNDABORT OFF;
SET XACT_ABORT ON;
IF DB_NAME() NOT LIKE N'Bridgeway[_]Validation[_]%' THROW 51400,'Validation fixtures are forbidden in the actual application database.',1;
IF EXISTS(SELECT 1 FROM core.UserAccount) THROW 51401,'Use a fresh empty validation database.',1;
CREATE TABLE #Results(Label nvarchar(200) NOT NULL);
GO
CREATE PROCEDURE #ExpectError @Label nvarchar(200),@Sql nvarchar(max),@Expected int
AS BEGIN
 BEGIN TRY EXEC sys.sp_executesql @Sql;END TRY
 BEGIN CATCH IF ERROR_NUMBER()<>@Expected THROW;INSERT #Results VALUES(@Label);RETURN;END CATCH;
 THROW 51402,'An expected rejection did not occur.',1;
END;
GO
