DECLARE @Twelfth uniqueidentifier=(SELECT WeekId FROM training.PlacementWeek WHERE PlacementId=@Placement AND WeekNumber=12);
EXEC api.SaveTask @Hr,@Twelfth,@Task OUTPUT,N'Week twelve task';
IF NOT EXISTS(SELECT 1 FROM training.Task WHERE TaskId=@Task AND WeekId=@Twelfth) THROW 51421,'Variable-length plans lost later-week tasks.',1;
INSERT #Results VALUES(N'Twelve unequal weeks total 200 hours and later-week tasks remain valid');
SET @Sql=N'UPDATE training.PlacementWeek SET AllocatedHours=20 WHERE WeekId='''+CONVERT(nvarchar(36),@Twelfth)+N''';';EXEC #ExpectError N'Placement allocations remain fixed after agreement',@Sql,51902;
DECLARE @ReadyHash binary(32)=HASHBYTES('SHA2_256',N'Synthetic boundary document');EXEC api.MarkFileAvailable @F,N'Validation',N'boundary-cv-not-real',@ReadyHash,800;
SET @Sql=N'UPDATE core.FileAsset SET StorageKey=N''Different content'' WHERE FileId='''+CONVERT(nvarchar(36),@F)+N''';';EXEC #ExpectError N'CV version content references cannot be replaced',@Sql,51907;
EXEC api.SetAccountStatus @Admin,@U,N'Suspended';
SET @Sql=N'DECLARE @id uniqueidentifier;EXEC api.RegisterFileMetadata '''+CONVERT(nvarchar(36),@U)+N''',N''cv.pdf'',N''application/pdf'',800,@id OUTPUT;';EXEC #ExpectError N'Suspended users cannot perform account actions',@Sql,51001;
EXEC api.SetAccountStatus @Admin,@U,N'Active';
SET @Sql=N'DECLARE @m uniqueidentifier=NULL;EXEC api.AcademicMeetingAction '''+CONVERT(nvarchar(36),@SupUser)+N''',@m OUTPUT,N''Save'','''+CONVERT(nvarchar(36),@S)+N''',N''Private'',NULL,30,N''https://zoom.us.example.com/j/123'';';
-- Assignment gate is tested independently of URL parsing: unassigned requests are rejected.
EXEC #ExpectError N'Academic requests cannot bypass current assignment',@Sql,51214;
EXEC api.RetireListing @Hr,@LongListing,0;
IF (SELECT Status FROM training.Placement WHERE PlacementId=@Placement)<>N'Active' THROW 51422,'Deleting a listing changed an existing placement.',1;
EXEC api.RetireListing @Hr,@LongListing,1;
EXEC api.SetCollegeProgram @Admin,18,2,12;
INSERT #Results VALUES(N'Listing retirement and restoration preserve existing placements');
IF NOT EXISTS(SELECT 1 FROM core.AuditEvent WHERE ActorId=@Admin AND Action=N'Account access changed') THROW 51423,'Administrative access changes were not audited.',1;
INSERT #Results VALUES(N'Administrative actions retain an actor-attributed audit trail');
DECLARE @Audit uniqueidentifier=(SELECT TOP(1) AuditId FROM core.AuditEvent);
SET @Sql=N'UPDATE core.AuditEvent SET Action=N''Rewritten history'' WHERE AuditId='''+CONVERT(nvarchar(36),@Audit)+N''';';EXEC #ExpectError N'Actor-attributed audit history is append-only',@Sql,51900;
SELECT N'PASS' AS Result,Label FROM #Results ORDER BY Label;
SELECT COUNT(*) AS PassedChecks FROM #Results;
GO
